const attr = (t, e) => String(t?.attr(e) || "").trim(),
  text = (t) => String(t?.text || "").trim(),
  utf8 = (t) => {
    if (!t) return "";
    try {
      return decodeURIComponent(escape(t));
    } catch (e) {
      try {
        return decodeURIComponent(t);
      } catch (err) {
        return t;
      }
    }
  };

class DefaultExtension extends MProvider {
  constructor() {
    super();
    this._memPref = {};
  }

  get supportsLatest() {
    return true;
  }

  get sourceKey() {
    return String(this.source?.id || "default");
  }

  pref(t) {
    try {
      const sp = new SharedPreferences();
      let val;
      if (typeof sp.getString === "function") {
        val = sp.getString(t, "");
      }
      if ((val === null || val === undefined || val === "") && typeof sp.get === "function") {
        val = sp.get(t);
      }
      if (val !== null && val !== undefined && String(val).trim() !== "") {
        return String(val).trim();
      }
    } catch (e) {}
    return Object.prototype.hasOwnProperty.call(this._memPref, t) ? String(this._memPref[t] ?? "").trim() : "";
  }

  setPref(t, val) {
    const str = String(val ?? "");
    this._memPref[t] = str;
    try {
      const sp = new SharedPreferences();
      if (typeof sp.setString === "function") {
        sp.setString(t, str);
      }
      if (typeof sp.set === "function") {
        sp.set(t, str);
      }
    } catch (e) {}
  }

  // 소스 ID별 서브 ID 및 탭 ID 연결 테이블
  get sourcePresets() {
    return {
      // 딸깍번역 서브 예시 (실제 소스 ID, 서브 ID, 카테고리 ID로 교체해서 사용)
      99001122: {
        board: "ddalkkak",
        category: "최신탭_카테고리_ID",
        popularCategory: "인기탭_카테고리_ID",
        tabs: [
          ["최신탭_카테고리_ID", "최신"],
          ["인기탭_카테고리_ID", "인기"],
          ["탭3_카테고리_ID", "탭이름3"],
          ["탭4_카테고리_ID", "탭이름4"]
        ]
      },
      16283411: {
        board: "somisoft",
        category: "dmXhWHD_fpPMT7WB-R3Pyb",
        popularCategory: "a68zpi8rFxRkr58kDe7jCb",
        tabs: [
          ["dmXhWHD_fpPMT7WB-R3Pyb", "동인"],
          ["a68zpi8rFxRkr58kDe7jCb", "야째"]
        ]
      },
      16283412: {
        board: "somisoft",
        category: "dGOMl65lS-N9TfN2UFaGYD",
        popularCategory: "ad4B2FKckxUKz3aGFP45yb",
        tabs: [
          ["dGOMl65lS-N9TfN2UFaGYD", "최신 카테고리"],
          ["ad4B2FKckxUKz3aGFP45yb", "인기 카테고리"]
        ]
      },
      16283401: {
        board: "lolita",
        category: "cIgVZ8ye_xLuX86NSCnjWb",
        popularCategory: "aJd_j2omqbGm969bCDnjWb",
        tabs: [
          ["cIgVZ8ye_xLuX86NSCnjWb", "최신 카테고리"],
          ["aJd_j2omqbGm969bCDnjWb", "인기 카테고리"]
        ]
      },
      24389802: {
        board: "trickal1557",
        category: "an4TiddUSCOJ9_YWrVZAab",
        popularCategory: "bTeK6XoT9sRAz938hRTkab",
        tabs: [
          ["an4TiddUSCOJ9_YWrVZAab", "최신 카테고리"],
          ["bTeK6XoT9sRAz938hRTkab", "인기 카테고리"]
        ]
      },
      86153710: {
        board: "qwerrewq",
        category: "dWMdooER1GTO945ZwHYAeb",
        popularCategory: "atCAYEjdHXV6vXwUG5XQeb",
        tabs: [
          ["dWMdooER1GTO945ZwHYAeb", "최신 카테고리"],
          ["atCAYEjdHXV6vXwUG5XQeb", "인기 카테고리"]
        ]
      },
      83418683: {
        board: "individual",
        category: "b-A6llERfpMqP-dS7nB5Sb",
        popularCategory: "dQ6qVQ3qTvIZD4nKw-UAab",
        tabs: [
          ["b-A6llERfpMqP-dS7nB5Sb", "최신 카테고리"],
          ["dQ6qVQ3qTvIZD4nKw-UAab", "인기 카테고리"]
        ]
      },
      83418684: {
        board: "individual",
        category: "dZtlVxLcquH-v_oqlLB5Sb",
        popularCategory: "dZtlVxLcquH-v_oqlLB5Sb",
        tabs: [["dZtlVxLcquH-v_oqlLB5Sb", "기본 카테고리"]]
      }
    };
  }

  get params() {
    const sourceId = Number(this.source?.id);
    const preset = this.sourcePresets[sourceId] || {
      board: "somisoft",
      category: "dmXhWHD_fpPMT7WB-R3Pyb",
      popularCategory: "a68zpi8rFxRkr58kDe7jCb",
      tabs: [
        ["dmXhWHD_fpPMT7WB-R3Pyb", "동인"],
        ["a68zpi8rFxRkr58kDe7jCb", "야째"]
      ]
    };

    const prefBoard = this.pref(`board_${this.sourceKey}`) || this.pref("board");
    const prefCat = this.pref(`category_${this.sourceKey}`) || this.pref("category");
    const prefPopCat = this.pref(`popularCategory_${this.sourceKey}`) || this.pref("popularCategory");

    const board = /^[A-Za-z0-9_-]+$/.test(prefBoard) ? prefBoard : preset.board;
    const category = /^[A-Za-z0-9_-]+$/.test(prefCat) ? prefCat : preset.category;
    const popularCategory = /^[A-Za-z0-9_-]+$/.test(prefPopCat) ? prefPopCat : preset.popularCategory;

    const parsedTabs = [];
    const seen = new Set();

    const addTab = (id, name) => {
      const cleanId = String(id || "").trim();
      const cleanName = String(name || "").trim();
      if (!cleanName) return;
      if (cleanId && !/^[A-Za-z0-9_-]+$/.test(cleanId)) return;
      const key = `${cleanId}::${cleanName}`;
      if (seen.has(key)) return;
      seen.add(key);
      parsedTabs.push([cleanId, cleanName]);
    };

    if (Array.isArray(preset.tabs)) {
      for (const [id, name] of preset.tabs) {
        addTab(id, name);
      }
    }

    const customTabsRaw = this.pref(`customTabs_${this.sourceKey}`);
    if (customTabsRaw) {
      for (const entry of customTabsRaw.split(/[\n,]+/)) {
        const line = entry.trim();
        if (!line) continue;
        const eqIdx = line.indexOf("=");
        if (eqIdx >= 0) {
          addTab(line.slice(eqIdx + 1), line.slice(0, eqIdx));
        } else {
          addTab(line, line);
        }
      }
    }

    if (category) addTab(category, `최신 (${category.slice(0, 6)}…)`);
    if (popularCategory && popularCategory !== category) {
      addTab(popularCategory, `인기 (${popularCategory.slice(0, 6)}…)`);
    }
    addTab("__ALL__", "전체 (카테고리 없음)");

    return { board, category, popularCategory, tabs: parsedTabs };
  }

  get board() {
    const { board: t } = this.params;
    if (!t || !/^[A-Za-z0-9_-]+$/.test(t)) {
      throw new Error("게시판 ID가 없습니다. 설정 또는 ID를 확인하세요.");
    }
    return `/s/${t}`;
  }

  validateCategory(t) {
    if (t === "__ALL__") return "";
    if (!t || !/^[A-Za-z0-9_-]+$/.test(t)) {
      throw new Error("카테고리 ID가 없습니다. 설정 또는 ID를 확인하세요.");
    }
    return t;
  }

  _categoryLabel(catValue) {
    const found = this.params.tabs.find(([id]) => String(id) === String(catValue));
    return found ? found[1] : (catValue || "전체");
  }

  _readFilter(filters, type, fallback) {
    if (!filters) return fallback;
    const arr = Array.isArray(filters) ? filters : Object.values(filters);
    const matched = arr.find((item) => {
      if (!item) return false;
      if (type === "category") return item.type === "category" || item.name === "카테고리 탭";
      if (type === "tabSave") return item.type === "tabSave" || item.name === "인기/최신 탭 저장";
      return false;
    });
    const target = matched || arr.find((item) => item && (item.type === type || item.name === type));
    if (!target) return fallback;

    if (Array.isArray(target.values) && target.values.length) {
      const rawIdx = target.state !== undefined && target.state !== null ? target.state : target.value;
      const idx = Number(rawIdx);
      if (Number.isFinite(idx) && idx >= 0 && idx < target.values.length) {
        const opt = target.values[idx];
        if (opt && opt.value !== undefined) return String(opt.value);
      }
    }
    const direct = target.value !== undefined ? target.value : target.state;
    if (direct && typeof direct === "object" && direct.value !== undefined) return String(direct.value);
    if (typeof direct === "string" && direct !== "" && !/^\d+$/.test(direct)) return direct;
    if (typeof direct === "number" || (typeof direct === "string" && /^\d+$/.test(direct))) return String(direct);
    return fallback;
  }

  getFilterList() {
    const { tabs } = this.params;
    return [
      {
        type_name: "SelectFilter",
        type: "category",
        name: "카테고리 탭",
        state: 0,
        values: tabs.map(([id, name]) => ({ type_name: "SelectOption", name, value: id }))
      },
      {
        type_name: "SelectFilter",
        type: "tabSave",
        name: "인기/최신 탭 저장",
        state: 0,
        values: [
          { type_name: "SelectOption", name: "저장하지 않음", value: "0" },
          { type_name: "SelectOption", name: "선택한 탭을 인기 탭에 저장", value: "1" },
          { type_name: "SelectOption", name: "선택한 탭을 최신 탭에 저장", value: "2" },
          { type_name: "SelectOption", name: "인기 탭 기본값 복원", value: "3" },
          { type_name: "SelectOption", name: "최신 탭 기본값 복원", value: "4" },
          { type_name: "SelectOption", name: "두 탭 모두 기본값 복원", value: "5" }
        ]
      }
    ];
  }

  getSourcePreferences() {
    return [
      {
        key: `board_${this.sourceKey}`,
        editTextPreference: {
          title: "게시판 ID",
          summary: "주소의 /s/<ID> 부분 (비워두면 소스 기본값 사용)",
          value: "",
          dialogTitle: "게시판 ID",
          dialogMessage: "예: somisoft"
        }
      },
      {
        key: `category_${this.sourceKey}`,
        editTextPreference: {
          title: "최신 탭 카테고리 ID",
          summary: "최신 목록에 표시할 category= 값",
          value: "",
          dialogTitle: "최신 탭 카테고리 ID",
          dialogMessage: "예: dmXhWHD_fpPMT7WB-R3Pyb"
        }
      },
      {
        key: `popularCategory_${this.sourceKey}`,
        editTextPreference: {
          title: "인기 탭 카테고리 ID",
          summary: "인기 목록에 표시할 category= 값",
          value: "",
          dialogTitle: "인기 탭 카테고리 ID",
          dialogMessage: "예: a68zpi8rFxRkr58kDe7jCb"
        }
      },
      {
        key: `customTabs_${this.sourceKey}`,
        editTextPreference: {
          title: "필터 탭 목록 추가 (선택)",
          summary: "탭이름=카테고리ID 형식으로 쉼표(,)로 구분해 추가할 수 있습니다.",
          value: "",
          dialogTitle: "필터 탭 목록 추가",
          dialogMessage: "예: 동인=dmXhWHD_fpPMT7WB-R3Pyb, 야째=a68zpi8rFxRkr58kDe7jCb"
        }
      }
    ];
  }

  getHeaders() {
    return { "User-Agent": "Mozilla/5.0", Referer: "https://kone.gg/" };
  }

  postPath(t) {
    const e = String(t)
      .replace(/&amp;/g, "&")
      .replace(/^https:\/\/kone\.gg(?=\/)/, "")
      .split(/[?#]/)[0];
    if (!/^\/s\/[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+$/.test(e)) throw new Error("Kone 게시글 주소가 아닙니다.");
    return e;
  }

  imageUrl(t) {
    const e = attr(t, "src");
    return /^https:\/\/[^\s\\]+$/.test(e) ? e : "";
  }

  async document(t) {
    const e = this._client || (this._client = new Client({ timeout: 20, connectTimeout: 5 })),
      r = await e.get(this.source.baseUrl + t, this.getHeaders());
    if (200 !== r.statusCode) throw new Error(`Kone 요청에 실패했습니다 (HTTP ${r.statusCode}).`);
    if (/<title>\s*Just a moment|id=["']cf-chl/i.test(r.body))
      throw new Error("WebView에서 사이트 인증을 완료한 후 다시 시도해 주세요.");
    return new Document(utf8(r.body).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, "")).body;
  }

  async list(t, e = "", targetCategory = "", filters = null) {
    if (!Number.isSafeInteger(t) || t < 1) throw new Error("올바른 페이지 번호가 아닙니다.");
    const r = this.board;
    const rawSelected = targetCategory || this._readFilter(filters, "category", this.params.category);
    const s = this.validateCategory(rawSelected);
    const a = String(e || "").trim().slice(0, 128);
    let notice = "";

    if (!targetCategory && t === 1 && !a && filters) {
      const action = this._readFilter(filters, "tabSave", "0");
      const label = this._categoryLabel(rawSelected);
      if (action === "1") {
        this.setPref(`popularCategory_${this.sourceKey}`, s);
        const check = this.pref(`popularCategory_${this.sourceKey}`);
        notice = `[인기 저장:${r}] ${label} (${check || "세션 반영"})`;
      } else if (action === "2") {
        this.setPref(`category_${this.sourceKey}`, s);
        const check = this.pref(`category_${this.sourceKey}`);
        notice = `[최신 저장:${r}] ${label} (${check || "세션 반영"})`;
      } else if (action === "3") {
        this.setPref(`popularCategory_${this.sourceKey}`, "");
        notice = `[인기 복원됨:${r}]`;
      } else if (action === "4") {
        this.setPref(`category_${this.sourceKey}`, "");
        notice = `[최신 복원됨:${r}]`;
      } else if (action === "5") {
        this.setPref(`popularCategory_${this.sourceKey}`, "");
        this.setPref(`category_${this.sourceKey}`, "");
        notice = `[모두 복원됨:${r}]`;
      }
    }

    const queryPrefix = s ? `category=${s}&` : "";
    const i = await this.document(`${r}?${queryPrefix}p=${t}${a ? "&q=" + encodeURIComponent(a) : ""}`),
      o = new Map();

    if (notice) {
      o.set("__notice__", { name: notice, link: `${r}/notice`, imageUrl: "" });
    }

    for (const item of i.select('a[class*="group/article"]')) {
      if (item.selectFirst(".lucide-pin")?.className) continue;
      const title = attr(item.selectFirst("div[title]"), "title");
      if (!title) continue;
      let link;
      try {
        link = this.postPath(attr(item, "href"));
      } catch (_) {
        continue;
      }
      if (!link.startsWith(r + "/")) continue;
      const img = this.imageUrl(item.select("img").find((imgEl) => attr(imgEl, "alt") === title));
      o.has(link) || o.set(link, { name: title, link, imageUrl: img });
    }
    const n = i.select("a[href]").some((aEl) => {
      const href = attr(aEl, "href").replace(/&amp;/g, "&");
      return href.includes(s ? `category=${s}` : `${r}?`) && new RegExp(`[?&]p=${t + 1}(?:&|$)`).test(href);
    });
    return { list: [...o.values()], hasNextPage: n };
  }

  getPopular(t) {
    return this.list(t, "", this.params.popularCategory);
  }

  getLatestUpdates(t) {
    return this.list(t, "", this.params.category);
  }

  search(t, e, r) {
    return this.list(e, t, "", r);
  }

  images(t) {
    return [...new Set(t.select(".article-prose .image-view-wrapper img").map((t) => this.imageUrl(t)).filter(Boolean))];
  }

  async getDetail(t) {
    const e = this.postPath(t),
      r = await this.document(e),
      s = text(r.selectFirst("header h1"));
    if (!s) throw new Error("게시글을 찾을 수 없습니다. 삭제 또는 접근 제한 여부를 확인해 주세요.");
    return {
      name: s,
      link: e,
      imageUrl: this.images(r)[0] || "",
      status: 1,
      author: attr(r.selectFirst('header a[aria-label][href^="/u/"]'), "aria-label"),
      description: text(r.selectFirst(".article-prose")).slice(0, 1e3),
      chapters: [{ name: s, url: e }],
    };
  }

  async getPageList(t) {
    const e = this.images(await this.document(this.postPath(t)));
    if (!e.length) throw new Error("게시글 본문에 표시할 이미지가 없습니다.");
    return e.map((t) => ({ url: t, headers: this.getHeaders() }));
  }
}
